-- Known names remain in the existing portable contact history when capture,
-- sync or import replaces a name, and when a merge removes the old person row.
-- This cannot reconstruct names discarded before this migration was installed.
CREATE TRIGGER contact_name_history_update BEFORE UPDATE OF display_name ON contacts
WHEN OLD.display_name IS NOT NEW.display_name AND NOT EXISTS (
 SELECT 1 FROM contact_history WHERE contact_id=OLD.id AND kind='contact-name' AND detail=OLD.display_name
)
BEGIN
 INSERT INTO contact_history(id,contact_id,kind,detail,occurred_at,created_at,updated_at)
 VALUES(lower(hex(randomblob(16))),OLD.id,'contact-name',OLD.display_name,NEW.updated_at,NEW.updated_at,NEW.updated_at);
END;
CREATE TRIGGER contact_name_history_merge BEFORE DELETE ON contacts
WHEN EXISTS(SELECT 1 FROM contact_merges WHERE merged_contact_id=OLD.id)
BEGIN
 INSERT INTO contact_history(id,contact_id,kind,detail,occurred_at,created_at,updated_at)
 SELECT lower(hex(randomblob(16))),m.survivor_contact_id,'contact-name',OLD.display_name,m.occurred_at,m.occurred_at,m.occurred_at
 FROM contact_merges m WHERE m.merged_contact_id=OLD.id AND NOT EXISTS (
  SELECT 1 FROM contact_history h WHERE h.contact_id=m.survivor_contact_id AND h.kind='contact-name' AND h.detail=OLD.display_name
 );
END;
